type Flags = typeof G;
type Txt = string | ((g: Flags) => string);

export interface Choice {
  t: string;
  go?: string;
  act?: string;
  if?: (g: Flags) => boolean;
  check?: { skill: SkillKey; dc: number; ok: string; fail: string };
}
export interface DNode {
  s: string;
  t: Txt;
  c?: Choice[] | ((g: Flags) => Choice[] | null);
  go?: string | ((g: Flags) => string);
  act?: string;
  do?: (g: Flags) => void;
}
export interface DTree { start: string | ((g: Flags) => string); nodes: Record<string, DNode> }

